void ApplyMigrations(AppDbContext db)
{
    // EF Core 9 manages its own transactions per migration;
    // wrapping Migrate() in a user transaction is no longer allowed.
    var strategy = db.Database.CreateExecutionStrategy();
    strategy.Execute(() =>
    {
        db.Database.Migrate();
    });
}

