using Microsoft.EntityFrameworkCore;

class CosmosContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 changed the default discriminator property from
        // "Discriminator" to "$type". To keep reading existing documents
        // that use "Discriminator", configure it explicitly.
        modelBuilder.Entity<Product>()
            .HasDiscriminator<string>("Discriminator");
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

using Microsoft.EntityFrameworkCore;

class CosmosQueryService
{
    // EF Core 9 removed synchronous query support for the Cosmos provider.
    // All queries must use async methods (ToListAsync, FirstAsync, etc.).
    async Task<List<Product>> GetProductsAsync(CosmosContext db)
    {
        return await db.Products.ToListAsync();
    }

    async Task<Product?> FindProductAsync(CosmosContext db, string name)
    {
        return await db.Products.FirstOrDefaultAsync(p => p.Name == name);
    }
}

